export function validateCount(count) {
  if (!Number.isSafeInteger(count) || count < 0) {
    throw new TypeError('count must be a non-negative integer');
  }
}

/**
 * Validates that an element is a safe integer within `0 .. count - 1`.
 * @param {unknown} element Value to validate.
 * @param {number} count Number of elements the structure holds.
 * @returns {void}
 */
export function validateElement(element, count) {
  if (!Number.isSafeInteger(element) || element < 0 || element >= count) {
    throw new RangeError(`element out of range: ${element}`);
  }
}

/**
 * Disjoint sets over the elements `0 .. count - 1`, joined by size and undone
 * in reverse order.
 *
 * Unions are recorded on a stack so they can be undone one at a time, or
 * rolled back to any earlier checkpoint. Path compression is intentionally
 * not performed on `find`, so the parent array only ever changes through
 * `union` and its exact reversal in `undo`.
 */
export class DisjointSets {
  #parent;
  #size;
  #components;
  #history;

  /**
   * @param {number} count How many elements the structure holds.
   */
  constructor(count) {
    validateCount(count);
    this.#parent = Array.from({ length: count }, (_, index) => index);
    this.#size = new Array(count).fill(1);
    this.#components = count;
    this.#history = [];
  }"}

