 * Disjoint sets over the elements `0 .. count - 1`, joined by size and undone
 * in reverse order.
 *
 * `find` deliberately performs no path compression: union already keeps
 * trees shallow (depth is `O(log count)`), and compression would rewrite
 * parent pointers that a later `undo`/`rollback` has no record of, silently
 * corrupting the structure once an old union is reversed. Instead, every
 * union pushes exactly the information needed to reverse it onto a stack,
 * and `checkpoint` simply names a depth in that stack.
 */
export class DisjointSets {
  #parent;
  #size;
  #components;
  #records;

  /**
   * @param {number} count How many elements the structure holds.
   */
  constructor(count) {
    validateCount(count);
    this.#parent = Array.from({ length: count }, (_, index) => index);
    this.#size = new Array(count).fill(1);
    this.#components = count;
    this.#records = [];
